export const VERSION: string;

export interface DisposalRegistryOptions<T = unknown> {
  /**
   * Optional identifier for diagnostics.
   * @default 'lite-cleanup'
   */
  name?: string;

  /**
   * Called after the FR path fires (target GC'd without explicit unregister).
   * Not called on explicit unregister. Use as a leak signal.
   */
  onCollect?: (tag: T | null) => void;

  /**
   * Called when a cleanup function throws.
   * If omitted, thrown errors are swallowed.
   * If onError itself throws, that error is swallowed as a last resort.
   */
  onError?: (err: unknown, tag: T | null) => void;
}

/**
 * Opaque handle returned by `register`. Pass to `unregister` to cancel
 * the finalizer. Handles are single-use; after unregister they are inert.
 */
export interface DisposalHandle {
  readonly disposed: boolean;
}

export interface DisposalRegistry<T = unknown> {
  /**
   * Register `target` for finalization. When `target` becomes unreachable
   * (and `unregister` was not called first), `cleanup` runs on the FR path.
   *
   * Held-value contract: `cleanup` MUST NOT close over `target`.
   */
  register(target: object, cleanup: () => void, tag?: T): DisposalHandle;

  /**
   * Cancel the finalizer for `handle`. Idempotent. Accepts `null` or
   * `undefined` as no-ops. Does NOT invoke cleanup; caller is responsible
   * for running cleanup manually if needed.
   */
  unregister(handle: DisposalHandle | null | undefined): void;

  /** Count of live (non-disposed) registrations. */
  size(): number;

  readonly name: string;
}

/**
 * Create a disposal registry backed by a single FinalizationRegistry.
 */
export function createDisposalRegistry<T = unknown>(
  options?: DisposalRegistryOptions<T>
): DisposalRegistry<T>;
